    Bug 1970018 - Panorama version of AddMessageBatch() to use default timestamp for missing "Date:" header. r=edicharry

    Differential Revision: https://phabricator.services.mozilla.com/D254897

diff --git a/mailnews/local/src/nsLocalMailFolder.cpp b/mailnews/local/src/nsLocalMailFolder.cpp
index 1cf0d8bbed9..9d17dde2bb1 100644
--- a/mailnews/local/src/nsLocalMailFolder.cpp
+++ b/mailnews/local/src/nsLocalMailFolder.cpp
@@ -3392,6 +3392,11 @@ nsresult nsMsgLocalMailFolder::AddMessageBatch2(
     // (We're using the old nsIMsgDatabase instead of going directly to
     // panorama, as we want to keep working with legacy code for now).
     RawHdr hdr = ParseMsgHeaders(raw);
+    // Malformed message might have a missing "Date:" header.
+    // Policy here is to fall back to current time.
+    if (hdr.date == 0) {
+      hdr.date = PR_Now();
+    }
     // TODO: Sanity check here? Are there cases where we'd reject a message?

     nsCOMPtr<nsIMsgDBHdr> dbHdr;
diff --git a/mailnews/local/test/unit/test_mailStoreEnvData.js b/mailnews/local/test/unit/test_mailStoreEnvData.js
index 66f6e22cbcf..49314ea1796 100644
--- a/mailnews/local/test/unit/test_mailStoreEnvData.js
+++ b/mailnews/local/test/unit/test_mailStoreEnvData.js
@@ -45,7 +45,7 @@ async function test_datelessMsgs() {
     Assert.notEqual(
       msg.date,
       0,
-      "Expect message without 'Date:' header to use date from msgStore."
+      "Expect message without 'Date:' header to use fallback timestamp."
     );
   }
